const items = $input.all();

let content = '';

for (const item of items) {
  const json = item.json;
  if (json.choices && json.choices.length > 0) {
    const message = json.choices[0].message;
    if (message && message.content) {
      try {
        let raw = message.content.trim();
        const codeBlockMatch = raw.match(/```json\s*([\s\S]*?)\s*```/);
        if (codeBlockMatch) raw = codeBlockMatch[1];
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          content = parsed.map((item, idx) => {
            return `${idx+1}. 【${item.date || ''}】${item.category || ''} ${item.title || ''}（来源：${item.source || '未知'}）\n- 发生了什么：${item.event || ''}\n- 对行业意味着什么：${item.industryImpact || ''}\n- 对人类生活意味着什么：${item.humanImpact || ''}\n- 原文链接：${item.link || '暂无'}`;
          }).join('\n\n');
        } else {
          content = raw;
        }
      } catch (e) {
        content = message.content;
      }
    }
  }
}

if (!content.trim()) {
  return { 
    feishuBody: JSON.stringify({
      msg_type: "text",
      content: { text: "今日暂无AI新闻。" }
    })
  };
}

// 清理所有不可见控制字符
content = content.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F\x80-\x9F\u200B-\u200D\uFEFF]/g, '');

// 手动构造飞书消息的 JSON 字符串
const feishuBody = JSON.stringify({
  msg_type: "text",
  content: {
    text: content
  }
});

return {
  feishuBody: feishuBody
};

const items = $input.all();

let token = '';
let newsItems = [];

for (const item of items) {
  const data = item.json || item;

  // 提取 token（来自获取 token 节点）
  if (data.tenant_access_token) {
    token = data.tenant_access_token;
  }

  // 提取新闻数据（来自二次翻译节点）
  if (Array.isArray(data)) {
    newsItems = newsItems.concat(data);
  } else if (data.title || data.link || data.summary || data.source) {
    newsItems.push(data);
  }
}

// 如果 token 和新闻都存在，合并输出
if (token && newsItems.length > 0) {
  return newsItems.map(item => ({
    json: {
      tenant_access_token: token,
      title: item.title || '',
      link: item.link || '',
      summary: item.summary || '',
      source: item.source || '',
      date: item.date || ''
    }
  }));
} else {
  // 如果数据不完整，返回错误信息
  return [{
    json: {
      error: '缺少 token 或新闻数据',
      token_exists: !!token,
      news_count: newsItems.length
    }
  }];
}

const items = $input.all();

let newsData = [];

for (const item of items) {
  const data = item.json || item;

  // 提取 feishuBody 内容
  const feishuBody = data.feishuBody || '';
  if (!feishuBody) continue;

  try {
    // 解析 feishuBody JSON
    const parsed = JSON.parse(feishuBody);
    const text = parsed.content?.text || '';

    // 按 "数字." 分割成单条新闻
    const blocks = text.split(/\n(?=\d+\.\s*【)/);

    for (const block of blocks) {
      if (!block.trim()) continue;

      // 提取日期、分类、标题、来源
      const dateMatch = block.match(/【([^】]+)】/);
      const titleMatch = block.match(/【[^】]+】\s*([^（]+?)\s*（来源：([^）]+)）/);
      const eventMatch = block.match(/- 发生了什么：([^\n]+)/);
      const industryMatch = block.match(/- 对行业意味着什么：([^\n]+)/);
      const humanMatch = block.match(/- 对人类生活意味着什么：([^\n]+)/);
      const linkMatch = block.match(/- 原文链接：([^\n]+)/);

      if (titleMatch) {
        const date = dateMatch ? dateMatch[1].trim() : '';
        const title = titleMatch[1] ? titleMatch[1].trim() : '';
        const source = titleMatch[2] ? titleMatch[2].trim() : '';

        newsData.push({
          title: title,
          link: linkMatch ? linkMatch[1].trim() : '',
          summary: eventMatch ? eventMatch[1].trim() : '',
          source: source,
          date: date
        });
      }
    }
  } catch (e) {
    console.error('解析 feishuBody 失败:', e);
  }
}

// 如果解析成功，返回新闻数据
if (newsData.length > 0) {
  return newsData.map(item => ({
    json: {
      title: item.title,
      link: item.link,
      summary: item.summary,
      source: item.source,
      date: item.date
    }
  }));
}

// 如果没有数据，返回错误信息
return [{
  json: {
    error: '解析新闻数据失败',
    received: items.length
  }
}];
